/// Form and joint angle assessment results generated by computer vision heuristics.
class FormSafetyCheck {
  final bool isSafe;
  final String message;
  final double kneeAngleDegrees;
  final bool hasValgusKneeCollapse;
  final String coachAudioCue;

  const FormSafetyCheck({
    required this.isSafe,
    required this.message,
    required this.kneeAngleDegrees,
    required this.hasValgusKneeCollapse,
    this.coachAudioCue = 'Keep up the safe form!',
  });
}

